+final _xmlToken = RegExp(
+  r'<(/?)([a-zA-Z][\w:.-]*)((?:\s+[\w:.-]+\s*=\s*"[^"]*")*)\s*(/?)>'
+  r'|<!\[CDATA\[(.*?)\]\]>',
+  dotAll: true,
+);
