Set<String> extractAttachmentReferences(String markdown) {
  final names = <String>{};
  final images = RegExp(r'!\[([^\]]*)\]\(([^)]+)\)', dotAll: true);
  for (final m in images.allMatches(markdown)) {
    _addIfAttachment(names, _stripTitle(m.group(2)!));
  }
