import 'package:dmtools/src/integrations/confluence/confluence_markdown.dart';

void main() {
  // 1. Normal synced block with paragraph (PR path).
  print('--- 1 synced block paragraph');
  print(confluenceStorageToMarkdown(
      '<h2>2. Get pre-signed URLs</h2>'
      '<ac:adf-extension>'
      '<ac:adf-node type="bodied-sync-block">'
      '<ac:adf-attribute key="resource-id">fedb2b81-0000</ac:adf-attribute>'
      '<ac:adf-content><p>Mahler responds</p></ac:adf-content>'
      '</ac:adf-node>'
      '</ac:adf-extension>'));

  // 2. Synced block MISSING ac:adf-content (fallback path).
  print('--- 2 synced block without adf-content (fallback)');
  print(confluenceStorageToMarkdown(
      '<ac:adf-node type="bodied-sync-block">'
      '<ac:adf-attribute key="resource-id">fedb2b81-0000</ac:adf-attribute>'
      '<p>payload</p>'
      '</ac:adf-node>'));

  // 3. Nested: synced block containing a draw.io extension.
  print('--- 3 nested extension inside synced block');
  print(confluenceStorageToMarkdown(
      '<ac:adf-node type="bodied-sync-block">'
      '<ac:adf-content>'
      '<p>before</p>'
      '<ac:adf-node type="extension">'
      '<ac:adf-attribute key="extension-key">drawio</ac:adf-attribute>'
      '</ac:adf-node>'
      '<p>after</p>'
      '</ac:adf-content>'
      '</ac:adf-node>'));

  // 4. TOC macro (Java drops it; what does Dart do?).
  print('--- 4 toc macro');
  print(confluenceStorageToMarkdown(
      '<h2>Intro</h2>'
      '<ac:structured-macro ac:name="toc"/>'
      '<p>Body</p>'));

  // 5. Inline adf-node inside a paragraph.
  print('--- 5 inline extension inside paragraph');
  print(confluenceStorageToMarkdown(
      '<p>See <ac:adf-node type="extension">'
      '<ac:adf-attribute key="extension-key">drawio</ac:adf-attribute>'
      '</ac:adf-node> below</p>'));

  // 6. multiBodiedSyncBlock type (other sync-block type).
  print('--- 6 multiBodiedSyncBlock');
  print(confluenceStorageToMarkdown(
      '<ac:adf-node type="multiBodiedSyncBlock">'
      '<ac:adf-content><p>real content</p></ac:adf-content>'
      '</ac:adf-node>'));
}

