+      _wrapListOrStructural(node, inner) ??
+      _wrapConfluenceBlock(node, inner) ??
+      _wrapAdfNode(node, inner) ??
+      _wrapAnchorOrImage(node) ??
+      _wrapInlineStyle(node, inner);
