+String _macroToMarkdown(_XmlNode node) {
+  final body = node.child('ac:plain-text-body')?.content ??
+      node.child('ac:rich-text-body')?.content ??
+      '';
+  final lang = node.attrs['ac:name'] == 'code'
+      ? node.child('ac:parameter')?.content ?? ''
