+  final rows = <List<String>>[];
+  _collectRows(node, rows);
+  if (rows.isEmpty) return '';
+  final buf = StringBuffer();
+  buf.write('| ${rows.first.join(' | ')} |\n');
+  buf.write('|${rows.first.map((_) => ' --- ').join('|')}|\n');
+  for (var i = 1; i < rows.length; i++) {
+    buf.write('| ${rows[i].join(' | ')} |\n');
+  }
