+  }
+  return buf.toString();
+}
+
+/// Indents a rendered item body's nested-list continuation lines.
+String _indentNested(String body) {
+  final lines = body.split('\n');
+  return [
+    for (var i = 0; i < lines.length; i++)
+      i == 0 || lines[i].trim().isEmpty ? lines[i] : '    ${lines[i]}',
+  ].join('\n');
+}
